using Studio.Core;
using Studio.Raple;

var adapter=new RapleAdapter(Path.GetFullPath(args.FirstOrDefault()??"../raple-realms-7-server"));var checks=0;
void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
void Reject(Action action,string label){try{action();}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
var file=Path.GetFullPath(adapter.Catalog().Single(e=>e.Id=="Cave Pirate Brawler").SourceFile);var supplied=File.ReadAllText(file);
const string source="""
using TKR.WorldServer.logic.behaviors;
namespace TKR.WorldServer.logic { public partial class BehaviorDb {
    private _ StudioOptional=()=>Behav().Init("Cave Pirate Brawler",new State("loop",StudioOptionalWrap(new StudioOptionalChildren(){ {20}, /* optional source note */ {11,null,System.DayOfWeek.Friday,new Shoot(20,count:3,fixedAngle:0,coolDown:100)} })));
    static Prioritize StudioOptionalWrap(System.Collections.Generic.IEnumerable<CycleBehavior> children)=>new Prioritize(System.Linq.Enumerable.ToArray(children));
    sealed class StudioOptionalChildren:System.Collections.Generic.IEnumerable<CycleBehavior> {
        readonly System.Collections.Generic.SortedDictionary<int,CycleBehavior[]> values=new();
        public void Add(int key,CycleBehavior primary=null,System.DayOfWeek mode=System.DayOfWeek.Friday,CycleBehavior fallback=null)=>values.Add(key,System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Where(new[]{primary,fallback},c=>c!=null)));
        public System.Collections.Generic.IEnumerator<CycleBehavior> GetEnumerator()=>System.Linq.Enumerable.SelectMany(values.Values,v=>v).GetEnumerator();
        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()=>GetEnumerator();
    }
} }
""";
var doc=new BehaviorDocument(source,adapter,sourceFile:file);var list=doc.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&n.Children.Any(c=>c.Kind=="InitializerEntry"));var first=list.Children[0];var second=list.Children[1];var ids=doc.Identities;
BehaviorNode Slot(Guid entry,string name)=>doc.Find(entry).Children.Single(n=>n.Argument?.Name==name);
var primary=Slot(first.Id,"primary");var fallback=Slot(first.Id,"fallback");
Check(first.Children.Count==2&&first.Children.All(n=>n.Argument?.Minimum==0&&n.Children.Count==0)&&doc.SourceDiagnostics().All(d=>!d.IsError),"Omitted optional Add inputs expose empty typed slots using the actual compiler defaults");
Check(Slot(second.Id,"primary").Children.Count==0&&Slot(second.Id,"fallback").Children.Single().Kind=="Shoot","Explicit null and omitted optional inputs share an empty authoring slot while supplied inputs remain native children");
Check(doc.AcceptsChild(primary.Id,"new Shoot(20)")&&!doc.AcceptsChild(fallback.Id,"new TimedTransition(100,\"loop\")"),"Empty optional slots retain the exact native conversion contract");
var overloadedSource=source.Replace("public void Add(int key,CycleBehavior primary=null", "public void Add(int key,CycleBehavior primary,System.DayOfWeek mode,Shoot fallback)=>values.Add(key,new[]{primary,fallback}); public void Add(int key,CycleBehavior primary=null");
var overloaded=new BehaviorDocument(overloadedSource,adapter,sourceFile:file);var overloadEntry=overloaded.Entities.Single().Root.Descendants().First(n=>n.Kind=="InitializerEntry");var overloadSlot=overloadEntry.Children.Single(n=>n.Argument?.Name=="fallback");var overloadIds=overloaded.Identities;
Reject(()=>overloaded.AddChild(overloadSlot.Id,"new Shoot(20)",d=>adapter.Validate(d,"Cave Pirate Brawler")),"Optional refill rejects a more-specific Add overload instead of silently changing native dispatch");Check(overloaded.Source==overloadedSource&&overloaded.Identities.SequenceEqual(overloadIds),"Rejected Add rebinding retains exact source, identities and history");
var singleSource=source.Replace(",System.DayOfWeek mode=System.DayOfWeek.Friday,CycleBehavior fallback=null","").Replace("new[]{primary,fallback}","new[]{primary}").Replace("{11,null,System.DayOfWeek.Friday,new Shoot(20,count:3,fixedAngle:0,coolDown:100)}","{11,new Shoot(20,count:3,fixedAngle:0,coolDown:100)}");
var single=new BehaviorDocument(singleSource,adapter,sourceFile:file);var singleEntry=single.Entities.Single().Root.Descendants().First(n=>n.Kind=="InitializerEntry");var singleSlot=singleEntry.Children.Single();Check(singleSlot.Argument?.Minimum==0&&singleSlot.Children.Count==0&&single.IsScalarChildSlot(singleEntry.Id),"One omitted optional Add behavior has a separate empty scalar owner");
var singleCreated=single.CreateInitializerEntry(singleEntry.Id,new Dictionary<string,string>{{"key","7"}},"new Shoot(20,count:4)",d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(single.Find(singleCreated).Children.Single().Children.Single().Kind=="Shoot","The single-expression creation API retains optional slot ownership and accepts a native child");
var singleOwner=single.Find(singleCreated).Children.Single();single.DeleteNode(singleOwner.Children.Single().Id,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(single.Find(singleOwner.Id).Children.Count==0,"Single optional child removal restores the native default without removing its entry");
var beforeRevision=doc.Revision;doc.AddChild(fallback.Id,"new Shoot(20,count:2,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,"Cave Pirate Brawler"));var added=Slot(first.Id,"fallback").Children.Single().Id;
Check(doc.Revision==beforeRevision+1&&Slot(first.Id,"primary").Children.Count==0&&Slot(first.Id,"fallback").Children.Single().Id==added,"Filling a later omitted Add input commits one revision and retains the earlier empty slot");
Check(doc.Source.Contains("(global::System.DayOfWeek)5")&&doc.Find(first.Id).Parameters.Single(p=>p.Name=="mode").Expression=="(global::System.DayOfWeek)5"&&doc.Source.Contains("/* optional source note */"),"Positional padding materializes the compiler's null and typed enum defaults without losing comments");
var fillSource=doc.Source;var fillIds=doc.Identities;Check(doc.Undo()&&doc.Source==source&&doc.Identities.SequenceEqual(ids)&&doc.Redo()&&doc.Source==fillSource&&doc.Identities.SequenceEqual(fillIds),"Optional fill Undo/Redo restores omitted syntax and all slot identities");
doc.DeleteNode(added,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(Slot(first.Id,"fallback").Children.Count==0&&Slot(first.Id,"fallback").Id==fallback.Id&&doc.Expression(doc.Find(first.Id)).EndsWith("null}"),"Removing an optional behavior restores the native null default without shifting later parameter positions");doc.Undo();
var replaced=doc.ReplaceChild(primary.Id,"new Shoot(20,count:8,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(Slot(first.Id,"fallback").Children.Single().Id==added&&Slot(first.Id,"primary").Children.Single().Id==replaced,"Independent optional replacement retains the neighboring populated input");
doc.DeleteNode(replaced,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(Slot(first.Id,"primary").Children.Count==0&&Slot(first.Id,"fallback").Children.Single().Id==added&&doc.Find(first.Id).Parameters.Single(p=>p.Name=="mode").Expression=="(global::System.DayOfWeek)5","Removing an earlier optional input preserves later scalar and child positions");doc.Undo();
doc.LockedNodes.Add(fallback.Id);doc.ReplaceChild(primary.Id,"new Shoot(20,count:7,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(Slot(first.Id,"fallback").Children.Single().Id==added,"An optional sibling slot lock permits independent edits to another input");Reject(()=>doc.DeleteNode(added),"An optional slot lock rejects removal of its native child");doc.LockedNodes.Clear();
var accepted=doc.Source;var acceptedIds=doc.Identities;Reject(()=>doc.ReplaceChild(primary.Id,"new TimedTransition(100,\"loop\")"),"Incompatible optional replacement rejects before accepted source mutation");Check(doc.Source==accepted&&doc.Identities.SequenceEqual(acceptedIds),"Rejected optional edits preserve accepted source and identities");
var output=Path.GetFullPath(".artifacts/optional-initializer");Directory.CreateDirectory(output);var project=new StudioProject{SourceFile=file,Source=doc.Source,EntityId="Cave Pirate Brawler",Identities=doc.Identities,Player=new(Invulnerable:true),Seed=7};
var path=Path.Combine(output,"optional.rbs");BehaviorDocument.Save(path,project);var saved=BehaviorDocument.Load(path);var reopened=new BehaviorDocument(saved.Source,adapter,saved.Identities,file);Check(reopened.Identities.SequenceEqual(doc.Identities),"Optional empty and populated slot identities persist through save/reopen");
await using(var runtime=await CompiledRuntime.StartAsync(adapter.ServerRoot,project)){await runtime.AdvanceAsync(new(),100);Check(runtime.Shots.Select(s=>s.Count).SequenceEqual(new[]{3,7,2}),"Compiled native Add runs populated optional inputs and skips its actual null defaults in sorted order");}
while(doc.Source!=source)if(!doc.Undo())throw new Exception("Could not restore optional source");
Check(doc.Identities.SequenceEqual(ids),"Complete optional edit history restores original omitted/null syntax and identities");
var revision=doc.Revision;var created=doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","7"}},new Dictionary<string,string>{{"fallback","new Shoot(20,count:5,fixedAngle:0,coolDown:100)"}},d=>adapter.Validate(d,"Cave Pirate Brawler"));
Check(doc.Revision==revision+1&&Slot(created,"primary").Children.Count==0&&Slot(created,"fallback").Children.Single().Kind=="Shoot","Creation permits omitted optional inputs and prepares a later populated input atomically");
var createdSource=doc.Source;var createdIds=doc.Identities;Check(doc.Undo()&&doc.Source==source&&doc.Redo()&&doc.Source==createdSource&&doc.Identities.SequenceEqual(createdIds),"One creation Undo/Redo retains optional slot identities and materialized defaults");
var emptyCreated=doc.CreateInitializerEntry(second.Id,new Dictionary<string,string>{{"key","9"},{"mode","System.DayOfWeek.Friday"}},new Dictionary<string,string>(),d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(doc.Find(emptyCreated).Children.All(n=>n.Children.Count==0),"Missing optional creation values reset populated prototype inputs to native defaults");doc.Undo();
var clipboard=doc.CopyNodes([first.Id,second.Id]);var copied=doc.PasteNodes(list.Id,1,clipboard,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(copied.Count==2&&Slot(copied[0],"primary").Children.Count==0&&Slot(copied[1],"fallback").Children.Count==1&&copied.All(id=>doc.Find(id).Children.All(n=>!ids.Select(i=>i.Id).Contains(n.Id))),"Clipboard entries preserve omitted/null/populated inputs and allocate fresh slot identities");doc.Undo();
var before=doc.Source;Reject(()=>doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","9"}},new Dictionary<string,string>{{"unknown","new Shoot(20)"}}),"Unknown optional creation input names reject atomically");Check(doc.Source==before,"Rejected optional creation retains accepted source");
await using(var runtime=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=doc.Source,Identities=doc.Identities})){await runtime.AdvanceAsync(new(),100);Check(runtime.Shots.Select(s=>s.Count).SequenceEqual(new[]{5,3}),"Native playback invokes the actual optional Add defaults for newly created and omitted entries");}
Check(File.ReadAllText(file)==supplied,"Optional Add authoring and native execution leave supplied game source unchanged");Console.WriteLine($"{checks} optional initializer checks passed.");
